import{_ as i,a0 as o,w as l,s as d,ao as r,I as p,x as t,a1 as a,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const $=JSON.parse('{"title":"awk 系列：如何使用 awk 的 ‘next’ 命令 | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：如何使用 awk 的 ‘next’ 命令 | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：如何使用 awk 的 ‘next’ 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：如何使用 awk 的 ‘next’ 命令 | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 6 - How to Use ‘next’ Command with Awk in Linux","title":"awk 系列：如何使用 awk 的 ‘next’ 命令","tag":"awk","desc":""},"relativePath":"awk/Part 6 - How to Use ‘next’ Command with Awk in Linux.md","filePath":"[post].md"}'),k={name:"awk/Part 6 - How to Use ‘next’ Command with Awk in Linux.md"};function u(c,n,w,m,x,g){const s=o("Link");return l(),d("div",null,[n[13]||(n[13]=r(`<h1 id="awk-系列-如何使用-awk-的-next-命令" tabindex="-1">awk 系列：如何使用 awk 的 ‘next’ 命令 <a class="header-anchor" href="#awk-系列-如何使用-awk-的-next-命令" aria-label="Permalink to “awk 系列：如何使用 awk 的 ‘next’ 命令”">​</a></h1><p><img src="http://www.tecmint.com/wp-content/uploads/2016/06/Use-next-Command-with-Awk-in-Linux.png" alt=""></p><p>在 awk 系列的第六節，我們來看一下<code>next</code>命令 ，它告訴 awk 跳過你所提供的所有剩下的模式和表達式，直接處理下一個輸入行。</p><p><code>next</code> 命令幫助你阻止運行命令執行過程中多餘的步驟。</p><p>要明白它是如何工作的, 讓我們來分析一下 food_list.txt 它看起來像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Food List Items</span></span>
<span class="line"><span>No      Item_Name               Price           Quantity</span></span>
<span class="line"><span>1       Mangoes                 $3.45              5</span></span>
<span class="line"><span>2       Apples                  $2.45              25</span></span>
<span class="line"><span>3       Pineapples              $4.45              55</span></span>
<span class="line"><span>4       Tomatoes                $3.45              25</span></span>
<span class="line"><span>5       Onions                  $1.45              15</span></span>
<span class="line"><span>6       Bananas                 $3.45              30</span></span></code></pre></div><p>運行下面的命令，它將在每個食物數量小於或者等於 20 的行後面標一個星號:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;$4 &lt;= 20 { printf &quot;%s\\t%s\\n&quot;, $0,&quot;*&quot; ; } $4 &gt; 20 { print $0 ;} &#39; food_list.txt </span></span>
<span class="line"><span></span></span>
<span class="line"><span>No	Item_Name		Price		Quantity</span></span>
<span class="line"><span>1	  Mangoes			$3.45		   5	*</span></span>
<span class="line"><span>2	  Apples			$2.45      25</span></span>
<span class="line"><span>3	  Pineapples	$4.45      55</span></span>
<span class="line"><span>4	  Tomatoes		$3.45      25 </span></span>
<span class="line"><span>5	  Onions			$1.45      15	*</span></span>
<span class="line"><span>6	  Bananas	    $3.45      30</span></span></code></pre></div><p>上面的命令實際運行如下:</p><ul><li>首先，它用<code>$4 &lt;= 20</code>表達式檢查每個輸入行的第四列（數量（Quantity））是否小於或者等於 20，如果滿足條件，它將在末尾打一個星號 <code>(*)</code>。</li><li>接着，它用<code>$4 &gt; 20</code>表達式檢查每個輸入行的第四列是否大於20，如果滿足條件，顯示出來。</li></ul><p>但是這裏有一個問題, 當第一個表達式用<code>{ printf &quot;%s\\t%s\\n&quot;, $0,&quot;**&quot; ; }</code>命令進行標註的時候在同樣的步驟第二個表達式也進行了判斷這樣就浪費了時間.</p><p>因此當我們已經用第一個表達式打印標誌行的時候就不再需要用第二個表達式<code>$4 &gt; 20</code>再次打印。</p><p>要處理這個問題, 我們需要用到<code>next</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;$4 &lt;= 20 { printf &quot;%s\\t%s\\n&quot;, $0,&quot;*&quot; ; next; } $4 &gt; 20 { print $0 ;} &#39; food_list.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No	Item_Name		Price		           Quantity</span></span>
<span class="line"><span>1	  Mangoes			$3.45		           5	*</span></span>
<span class="line"><span>2	  Apples			$2.45              25</span></span>
<span class="line"><span>3	  Pineapples	$4.45              55</span></span>
<span class="line"><span>4	  Tomatoes		$3.45              25 </span></span>
<span class="line"><span>5	  Onions			$1.45              15	*</span></span>
<span class="line"><span>6	  Bananas	    $3.45              30</span></span></code></pre></div><p>當輸入行用<code>$4 &lt;= 20</code> <code>{ printf &quot;%s\\t%s\\n&quot;, $0,&quot;*&quot; ; next ; }</code>命令打印以後，<code>next</code>命令將跳過第二個<code>$4 &gt; 20</code> <code>{ print $0 ;}</code>表達式，繼續判斷下一個輸入行，而不是浪費時間繼續判斷一下是不是當前輸入行還大於 20。</p><p><code>next</code>命令在編寫高效的命令腳本時候是非常重要的，它可以提高腳本速度。本系列的下一部分我們將來學習如何使用 awk 來處理標準輸入（STDIN）。</p><p>希望這篇文章對你有幫助，你可以給我們留言。</p><hr>`,18)),p("p",null,[n[1]||(n[1]=t("via: ",-1)),a(s,{href:"http://www.tecmint.com/use-next-command-with-awk-in-linux/"},{default:e(()=>[...n[0]||(n[0]=[t("http://www.tecmint.com/use-next-command-with-awk-in-linux/",-1)])]),_:1})]),p("p",null,[n[5]||(n[5]=t("作者：",-1)),a(s,{href:"http://www.tecmint.com/author/aaronkili/"},{default:e(()=>[...n[2]||(n[2]=[t("Aaron Kili",-1)])]),_:1}),n[6]||(n[6]=t(" 譯者：",-1)),a(s,{href:"https://github.com/kokialoves"},{default:e(()=>[...n[3]||(n[3]=[t("kokialoves",-1)])]),_:1}),n[7]||(n[7]=t(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:e(()=>[...n[4]||(n[4]=[t("wxy",-1)])]),_:1})]),p("p",null,[n[10]||(n[10]=t("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[8]||(n[8]=[t("LCTT",-1)])]),_:1}),n[11]||(n[11]=t(" 原創編譯，",-1)),a(s,{href:"https://linux.cn/"},{default:e(()=>[...n[9]||(n[9]=[t("Linux中國",-1)])]),_:1}),n[12]||(n[12]=t(" 榮譽推出",-1))])])}const C=i(k,[["render",u]]);export{$ as __pageData,C as default};
